#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

#define Rep(i,N) for(int i = 0; i < N; i++)

inline void chmax(int &a, int b) { a = max(a, b); }

int main() {
    int N, M;
    int A[5005], B[5005];
    int maxv = 0;

    scanf("%d %d", &N, &M);
    Rep(i, N) scanf("%d", &A[i]);
    Rep(i, M) scanf("%d", &B[i]);

    vector<int> dp(5005, 0);
    Rep(i, M) {
        for (int j = N - 1; j >= 0; j--) {
            if(A[j] == B[i]) chmax(dp[j + 1], dp[j] + 1);
            chmax(maxv, dp[j + 1]);
        }
    }

    printf("%d\n", maxv);
    return 0;
}

